// ═══════════════════════════════════════════════════════════════
// BUILD UNIFIED PROMPT — Merged Interview Engine
// ═══════════════════════════════════════════════════════════════
// Replaces 3 separate code nodes (analyze-answer, generate-turn,
// targeted-followup) with a single prompt that evaluates the
// candidate's answer AND generates the next interviewer turn in
// one API call.
// ═══════════════════════════════════════════════════════════════

const input = $input.first().json.body || $input.first().json;

const {
  question,
  answer,
  resumeText,
  jdText,
  history,
  blueprint,
  competencyIds,
  questionType = 'technical',
  isAlreadyFollowUp = false,
  analysis,
  planItem,
} = input;

const truncate = (text, max) =>
  !text ? '' : text.length > max ? `${text.slice(0, max)}...[truncated]` : text;

// ─── History ──────────────────────────────────────────────────
const historyArr = history || [];
const questionsAsked = historyArr.filter(item => item.type !== 'follow_up').length;
const recentHistory = historyArr.slice(-4);
const historyText = recentHistory.length
  ? recentHistory
      .map((item, i) => `Q${i + 1}: ${item.question}\nA${i + 1}: ${item.answer || '(no answer)'}`)
      .join('\n\n')
  : 'None — this is the opening turn.';

const lastItem = historyArr.length ? historyArr[historyArr.length - 1] : null;

// ─── Competencies ─────────────────────────────────────────────
const targetedCompetencies = (blueprint?.competencies || []).filter(item =>
  (competencyIds || []).includes(item.id)
);

// ─── Word count & length note ─────────────────────────────────
const wordCount = (answer || '').trim().split(/\s+/).filter(Boolean).length;
const hasAnswer = !!(answer && answer.trim() && answer.trim() !== '(no answer)');
const lengthNote = !hasAnswer
  ? ''
  : wordCount < 15
    ? `The answer is very short (${wordCount} words). Honest uncertainty must advance, not trigger a follow-up.`
    : wordCount < 40
      ? `The answer is short (${wordCount} words). Assess whether it still provides enough relevant evidence.`
      : '';

// ─── Focus instruction (from plan or fallback) ───────────────
const extractedTools = analysis?.extractedTools || [];
let focusInstruction = '';
let questionTypeTarget = questionType || 'technical';

if (planItem) {
  questionTypeTarget = planItem.question_type || 'technical';

  if (planItem.category === 'gap_probe') {
    const gap = planItem.gap_ref;
    focusInstruction = `CATEGORY: gap_probe
Gap to probe: "${gap?.description || planItem.objective}"
Approach: "${gap?.probe_direction || "Ask how the candidate's background transfers to this area."}"
Tone: curious and warm, never accusatory.`;

  } else if (planItem.category === 'problem_solving') {
    focusInstruction = `CATEGORY: problem_solving
Objective: ${planItem.objective || 'Test practical reasoning and decision-making.'}
Ask one real-world scenario or trade-off question.
Use formats such as "How would you approach..." or "Walk me through how you would handle...".
Do not ask for a definition or memorised explanation.`;

  } else if (planItem.category === 'cultural') {
    focusInstruction = `CATEGORY: cultural
Objective: ${planItem.objective || 'Understand work style, collaboration, and team fit.'}
Ask about one concrete situation, preference, or working style.
Use formats such as "Tell me about a time when..." or "How do you typically...".`;

  } else {
    const tool = planItem.target_tool || 'the required skill';
    const verificationMode = planItem.verification_mode || 'baseline_check';
    const matchingTool = extractedTools.find(
      item => item.name?.toLowerCase() === tool.toLowerCase()
    );
    const resumeContext = matchingTool?.resume_context || '';

    if (verificationMode === 'verify_claim') {
      focusInstruction = `CATEGORY: ${planItem.category} - VERIFY CLAIM
Tool: "${tool}"
Candidate resume context: "${resumeContext || 'Listed on resume'}"
Objective: ${planItem.objective}

Ask about one specific real experience:
- a decision they made,
- a problem they solved,
- an implementation detail,
- or a trade-off they navigated using ${tool}.

Do not ask a vague question such as "Tell me about your experience with ${tool}."`;

    } else {
      focusInstruction = `CATEGORY: ${planItem.category} - BASELINE CHECK
Tool: "${tool}"
This skill is required by the JD but is not evident in the resume.
Objective: ${planItem.objective}

Ask one accessible awareness question about:
- what problem ${tool} solves,
- when they would use it,
- or how it fits into a practical workflow.

Do not ask deep implementation questions.`;
    }
  }

} else {
  const fallbackStages = [
    { instruction: 'Ask one foundational question about the primary technology required for the role.', type: 'technical' },
    { instruction: 'Ask one question about a core principle or trade-off in a key JD technology.', type: 'technical' },
    { instruction: 'Ask one question about an engineering design decision relevant to the role.', type: 'technical' },
    { instruction: 'Ask one hands-on implementation or debugging scenario using a key tool.', type: 'technical' },
    { instruction: 'Ask about one specific project from the resume and a decision made within it.', type: 'technical' },
    { instruction: 'Ask how one resume experience applies to a JD requirement.', type: 'technical' },
    { instruction: "Ask how the candidate's background transfers to a JD gap or unfamiliar area.", type: 'situational' },
    { instruction: 'Ask one practical, scenario-based problem-solving question.', type: 'situational' },
    { instruction: 'Ask one question about collaboration, feedback, or handling disagreement.', type: 'cultural' },
    { instruction: 'Ask one question about work environment, adaptability, or role motivation.', type: 'cultural' },
  ];
  const stageIndex = Math.min(questionsAsked, fallbackStages.length - 1);
  focusInstruction = fallbackStages[stageIndex].instruction;
  questionTypeTarget = fallbackStages[stageIndex].type;
}

// ─── Insufficiency strategy block ─────────────────────────────
const insufficiencyStrategyBlock = `Strategy by insufficiency reason:
- lacks_depth: probe the specific mechanism, process, or decision behind what they already said — go one level deeper into something they mentioned.
- lacks_evidence: ask for a concrete outcome, metric, or result tied to the claim they made.
- vague: ask them to specify exactly which of several plausible things they meant, referencing the ambiguity directly.`;

// ═══════════════════════════════════════════════════════════════
// BUILD THE UNIFIED PROMPT
// ═══════════════════════════════════════════════════════════════
let prompt;

if (hasAnswer) {
  // ─── FULL PIPELINE: Evaluate answer + Generate next turn ────
  prompt = `You are Alex, a warm and professional technical recruiter conducting a live interview.

Perform two tasks in sequence: (1) evaluate the candidate's answer, then (2) generate your next interviewer turn based on that evaluation.

━━━━━━━━━━━━ CONTEXT ━━━━━━━━━━━━

Current question:
"${question}"

Question type: ${questionType}
Is this question already a follow-up: ${isAlreadyFollowUp ? 'yes' : 'no'}

Candidate answer:
"${answer}"

Resume:
"""
${truncate(resumeText, 2000)}
"""

Job description:
"""
${truncate(jdText, 1200)}
"""

Recent interview history:
${historyText}

Target competencies:
${targetedCompetencies.length ? JSON.stringify(targetedCompetencies, null, 2) : 'None specified.'}

${lengthNote}

━━━━━━━━━━━━ TASK 1: EVALUATE THE ANSWER ━━━━━━━━━━━━

HARD CONSTRAINT (check first):
If "Is this question already a follow-up" is yes, OR question type is not "technical", recommended_action MUST be "advance". Skip the decision logic below.

Otherwise, for a primary technical question, choose exactly one outcome:

advance:
- Sufficient primary technical answer.
- Honest uncertainty, refusal, or a short but relevant answer.
- Answer is "(no answer)".
- When uncertain.

follow_up:
- Answer is relevant but materially insufficient — engages with the question but avoids the requested mechanics, trade-offs, or real-world specifics.
- Probe exactly one missing technical detail.

rephrase_primary:
- Entire response asks for clarification, says they don't understand, or is clearly off-topic.

Calibration:
- "I don't know" → advance.
- Partial answer with genuine technical evidence → usually advance.
- Textbook definition avoiding mechanics/trade-offs/real-world usage → may use follow_up.
- Any genuine attempt to address the question → not off-topic.
- If uncertain → advance.

━━━━━━━━━━━━ TASK 2: GENERATE NEXT TURN ━━━━━━━━━━━━

Based on your Task 1 evaluation, generate the interviewer's next turn.

FOCUS FOR NEXT QUESTION (used when recommended_action is "advance"):
${focusInstruction || 'Ask a foundational technical question grounded in the job description.'}

--- INTERVIEWER_TEXT RULES ---
interviewer_text is an acknowledgement only.
- One or two natural sentences. No question, no question mark, no question wording.
- Do not include, paraphrase, preview, or hint at question_text.
- Do not score, criticise, summarise, or reveal internal assessment.
- Do not use generic evaluative praise (great, excellent, perfect, wonderful, fantastic, amazing).
- For advance: acknowledge neutrally, transition smoothly. Example: "Thanks for walking me through that."
- For follow_up: acknowledge neutrally, do not imply insufficiency. Example: "Got it — I'd like to dig into one part of that a bit more."
- For rephrase_primary: acknowledge without blame. Example: "No problem — let me ask that a different way."
- For short answers or honest uncertainty: remain low-pressure and respectful.

--- QUESTION_TEXT RULES ---
question_text must contain exactly one question with no acknowledgement, transition, praise, or preamble.

If recommended_action is "advance":
- Generate one specific question from the focus instruction above.
- Ground it in the resume and job description.
- Do not combine multiple questions.
- Do not invent experience, projects, tools, or metrics not present in the resume or JD.

If recommended_action is "follow_up":
- Target exactly one missing technical detail from your evaluation.
- Ground the question in something from the candidate's answer (a claim, phrase, tool, decision, project, or implementation detail).
- Do not repeat or broadly reword the original question.
- Do not use generic wording: "tell me more", "go deeper", "elaborate", "be more specific", "give an example", or equivalents.
- Name the specific detail being asked about.
${insufficiencyStrategyBlock}
- Example — if candidate said "I used caching to speed things up":
  ✅ "What did you use for the caching layer, and what made you choose it over the alternatives?"
  ❌ "Can you elaborate on the caching approach you mentioned?"

If recommended_action is "rephrase_primary":
- Preserve the same competency being evaluated.
- Use clear, concrete, accessible language.
- Do not make the technical standard easier; only make the wording easier to understand.
- Do not introduce tools, projects, metrics, or scenarios not grounded in the original question.

━━━━━━━━━━━━ OUTPUT ━━━━━━━━━━━━

Field rules for non-relevant fields:
- advance → insufficiency_reason, follow_up_direction, rephrase_direction all null
- follow_up → rephrase_direction null
- rephrase_primary → insufficiency_reason, follow_up_direction null

Return ONLY valid JSON:
{
  "authenticity_signal": "genuine" | "vague" | "suspicious" | "inconsistent",
  "depth_signal": "deep" | "surface" | "empty",
  "competency_evidence": [{"competency": "...", "evidence": "..."}],
  "note": "Balanced recruiter note, max two sentences.",
  "recommended_action": "advance" | "follow_up" | "rephrase_primary",
  "confidence": 0.0,
  "follow_up_prompted": true | false,
  "answer_was_irrelevant": true | false,
  "insufficiency_reason": "lacks_depth" | "lacks_evidence" | "vague" | "irrelevant" | null,
  "follow_up_direction": "One specific missing detail, or null.",
  "rephrase_direction": "How to restate the question, or null.",
  "interviewer_text": "Acknowledgement only. No question marks.",
  "question_text": "One question only. No acknowledgement."
}`;

} else {
  // ─── FIRST TURN: No answer to evaluate — generate opening ──
  prompt = `You are Alex, a warm and professional technical recruiter conducting a live interview.

Generate the next interviewer turn.

${lastItem ? `Candidate's most recent answer:\n"${lastItem.answer || '(no previous answer)'}"` : 'This is the first question of the interview.'}

Focus for the question:
${focusInstruction || 'Ask a foundational technical question grounded in the job description.'}

Candidate resume:
"""
${truncate(resumeText, 1800)}
"""

Job description:
"""
${truncate(jdText, 1000)}
"""

Recent interview history:
${historyText}

--- INTERVIEWER_TEXT RULES ---
interviewer_text is a brief, warm opening or transition.
- One or two natural sentences. No question, no question mark.
${!lastItem
    ? '- For the first question: a brief, warm greeting. Example: "Thanks for joining — let\'s get started."'
    : '- Acknowledge the previous answer neutrally and transition smoothly.'}
- Do not use generic evaluative praise (great, excellent, perfect, wonderful, fantastic, amazing).

--- QUESTION_TEXT RULES ---
- Exactly one question. No acknowledgement, transition, or preamble.
- Ground it in the resume and job description.
- Do not combine multiple questions.
- Do not invent experience, projects, tools, or metrics not present in the resume or JD.

Return ONLY valid JSON:
{
  "interviewer_text": "Opening or transition. No question marks.",
  "question_text": "One question only. No acknowledgement."
}`;
}

// ─── Computed fields (attached after API call by Parse node) ──
const resolvedQuestionType = questionTypeTarget;
const resolvedShouldContinue = true;

return [{ json: { prompt, hasAnswer, resolvedQuestionType, resolvedShouldContinue } }];

// ═══════════════════════════════════════════════════════════════
// PARSE & ENRICH — Post-OpenAI response processing
// ═══════════════════════════════════════════════════════════════
// Parses the LLM response and adds deterministic computed fields
// that should not be left to the model (turn_type, question_type,
// should_continue).
//
// For first-turn responses (no answer was evaluated), fills in
// default analysis values so the response shape is always
// consistent regardless of whether analysis was performed.
// ═══════════════════════════════════════════════════════════════

const content = JSON.parse($input.first().json.choices[0].message.content);
const buildNode = $node["Build Unified Prompt"];
const hasAnswer = buildNode.json.hasAnswer;

if (hasAnswer) {
  // ─── Full pipeline response: add computed fields ────────────
  content.turn_type = content.recommended_action === 'advance' ? 'question' : 'follow_up';
  content.question_type = buildNode.json.resolvedQuestionType;
  content.should_continue = buildNode.json.resolvedShouldContinue;
} else {
  // ─── First turn response: fill default analysis values ──────
  content.authenticity_signal = null;
  content.depth_signal = null;
  content.competency_evidence = [];
  content.note = null;
  content.recommended_action = 'advance';
  content.confidence = 1.0;
  content.follow_up_prompted = false;
  content.answer_was_irrelevant = false;
  content.insufficiency_reason = null;
  content.follow_up_direction = null;
  content.rephrase_direction = null;
  content.turn_type = 'question';
  content.question_type = buildNode.json.resolvedQuestionType;
  content.should_continue = buildNode.json.resolvedShouldContinue;
}

return [{ json: content }];
